test("moderator application entry routes recovery and unfinished setup safely", () => {
  const cases = [
    { sourceReady: false, plan: null, destination: "/plan-bereit" },
    { sourceReady: true, plan: null, destination: "/plan-start" },
  ]
  for (const item of cases) {
